7	namespace seed_a_backend.Api.Infrastructure;
8	
9	public class AppDbContext(DbContextOptions<AppDbContext> options) : DbContext(options)
10	{
11	    /// <summary>
12	    /// Name des CHECK-Constraints, der erzwingt, dass `BookingPosition.BookingId`/`PriceCategoryId`
13	    /// immer gemeinsam null oder gemeinsam gesetzt sind (AD-2). Als gemeinsam referenzierte Konstante
14	    /// statt eines duplizierten String-Literals in Produktions- und Testcode, damit eine künftige
15	    /// Umbenennung bereits beim Kompilieren der Tests auffällt statt erst zur Laufzeit.
16	    /// </summary>
17	    public const string BookingPositionBeideNullOderBeideGesetztConstraintName =
18	        "CK_BookingPositions_BookingId_PriceCategoryId_BeideNullOderBeideGesetzt";
19	
20	    public DbSet<Venue> Venues => Set<Venue>();
21	    public DbSet<Room> Rooms => Set<Room>();
22	    public DbSet<Event> Events => Set<Event>();
23	    public DbSet<PriceCategory> PriceCategories => Set<PriceCategory>();
24	    public DbSet<Booking> Bookings => Set<Booking>();
25	    public DbSet<BookingPosition> BookingPositions => Set<BookingPosition>();
26	
27	    protected override void OnModelCreating(ModelBuilder modelBuilder)
28	    {
29	        modelBuilder.Entity<Venue>(entity =>
30	        {
31	            entity.HasMany(v => v.Rooms)
32	                .WithOne()
33	                .HasForeignKey(r => r.VenueId)
34	                .OnDelete(DeleteBehavior.Restrict);
35	        });
36	
37	        modelBuilder.Entity<Room>(entity =>
38	        {
39	            entity.HasMany(r => r.Events)
40	                .WithOne()
41	                .HasForeignKey(e => e.RoomId)
42	                .OnDelete(DeleteBehavior.Restrict);
43	
44	            ConfigureJsonListConversion<IReadOnlyList<string>, string>(entity.Property(r => r.RowLabels), list => list);
45	            ConfigureJsonListConversion<IReadOnlyCollection<int>, int>(entity.Property(r => r.AisleColumns), list => list);
46	        });
47	
48	        modelBuilder.Entity<Event>(entity =>
49	        {
50	            entity.HasMany(e => e.PriceCategories)
51	                .WithOne()
52	                .HasForeignKey(pc => pc.EventId)
53	                .OnDelete(DeleteBehavior.Restrict);
54	
55	            entity.HasMany(e => e.BookingPositions)
56	                .WithOne()
57	                .HasForeignKey(bp => bp.EventId)
58	                .OnDelete(DeleteBehavior.Restrict);
59	        });
60	
61	        modelBuilder.Entity<PriceCategory>(entity =>
62	        {
63	            entity.Property(pc => pc.Preis).HasPrecision(10, 2);
64	        });
65	
66	        modelBuilder.Entity<Booking>(entity =>
67	        {
68	            entity.Property(b => b.Reference)
69	                .HasMaxLength(8)
70	                .IsRequired()
71	                .UseCollation("SQL_Latin1_General_CP1_CI_AS");
72	            entity.HasIndex(b => b.Reference).IsUnique();
73	
74	            entity.HasMany(b => b.Positions)
75	                .WithOne()
76	                .HasForeignKey(bp => bp.BookingId)
77	                .OnDelete(DeleteBehavior.Restrict);
78	        });
79	
80	        modelBuilder.Entity<BookingPosition>(entity =>
81	        {
82	            entity.HasOne<PriceCategory>()
83	                .WithMany()
84	                .HasForeignKey(bp => bp.PriceCategoryId)
85	                .OnDelete(DeleteBehavior.Restrict);
86	
87	            entity.HasIndex(bp => new { bp.EventId, bp.RowLabel, bp.ColumnNumber })
88	                .IsUnique()
89	                .HasFilter("[CancelledAtUtc] IS NULL");
90	
91	            entity.ToTable(t => t.HasCheckConstraint(
92	                BookingPositionBeideNullOderBeideGesetztConstraintName,
93	                "([BookingId] IS NULL AND [PriceCategoryId] IS NULL) OR ([BookingId] IS NOT NULL AND [PriceCategoryId] IS NOT NULL)"));
94	        });
95	    }
96	
97	    /// <summary>
98	    /// Persistiert eine Listen-Property als JSON-String mit einem korrekten Value-Comparer für
99	    /// EF-Core-Change-Tracking. Gemeinsame Konfiguration für `Room.RowLabels`/`Room.AisleColumns`,
100	    /// die sich zuvor nur im Element-/Property-Typ unterschied. `fromList` wrappt das deserialisierte
101	    /// `List&lt;TItem&gt;` in `TCollection` beim Aufrufer statt per ungesichertem `(TCollection)(object)`-Cast,
102	    /// der nur zufällig funktioniert, wenn `List&lt;TItem&gt;` tatsächlich in `TCollection` konvertierbar ist.
103	    /// </summary>
104	    private static void ConfigureJsonListConversion<TCollection, TItem>(
105	        PropertyBuilder<TCollection> property,
106	        Func<List<TItem>, TCollection> fromList)
107	        where TCollection : class, IReadOnlyCollection<TItem>
108	    {
109	        var empty = fromList(new List<TItem>());
110	
111	        property
112	            .HasConversion(
113	                v => JsonSerializer.Serialize(v, JsonSerializerOptions.Default),
114	                v => fromList(JsonSerializer.Deserialize<List<TItem>>(v, JsonSerializerOptions.Default) ?? new List<TItem>()))
115	            .Metadata.SetValueComparer(new ValueComparer<TCollection>(
116	                (a, b) => (a ?? empty).SequenceEqual(b ?? empty),
117	                v => (v ?? empty).Aggregate(0, (hash, item) => HashCode.Combine(hash, item)),
118	                v => fromList((v ?? empty).ToList())));
119	    }
120	}
